// Harry Potter card data, generated by scripts/prepare-hp-vocabulary.py and loaded one level at a time.
export type HpExample = { sentenceId: string; text: string; surface: string; speaker: string; movie: string; page: string; ko: string };
export type HpCard = { id: string; word: string; surface: string; meaning: string; alternative: string; note: string; level: string; type: string; pos: string; reviewed: boolean; examples: HpExample[] };
export const hpLevels = ["A1", "A2", "B1", "B2", "C1", "C2", "미분류"] as const;
export type HpLevel = typeof hpLevels[number];
// Literal paths so the bundler emits each level as its own chunk.
const loaders: Record<HpLevel, () => Promise<{ default: unknown }>> = {
  A1: () => import("./hp-vocabulary/a1.json"),
  A2: () => import("./hp-vocabulary/a2.json"),
  B1: () => import("./hp-vocabulary/b1.json"),
  B2: () => import("./hp-vocabulary/b2.json"),
  C1: () => import("./hp-vocabulary/c1.json"),
  C2: () => import("./hp-vocabulary/c2.json"),
  미분류: () => import("./hp-vocabulary/unclassified.json"),
};
const pending = new Map<HpLevel, Promise<HpCard[]>>();
export function loadHpLevel(level: HpLevel) {
  let request = pending.get(level);
  if (!request) {
    request = loaders[level]().then((module) => module.default as HpCard[]);
    pending.set(level, request);
    // A failed download can be retried.
    request.catch(() => pending.delete(level));
  }
  return request;
}
// "전체" and rounds saved before levels were recorded need every level.
export const hpLevelsFor = (level: string | undefined): readonly HpLevel[] =>
  (hpLevels as readonly string[]).includes(level ?? "") ? [level as HpLevel] : hpLevels;
